{"code": "def get_values(nums, ops):
    if len(nums) == 1:
        return {nums[0]}

    values = set()
    for i in range(len(ops)):
        # Split at operator i
        left_nums = nums[:i+1]
        right_nums = nums[i+1:]
        left_ops = ops[:i]
        right_ops = ops[i+1:]

        left_vals = get_values(left_nums, left_ops)
        right_vals = get_values(right_nums, right_ops)

        op = ops[i]
        for l in left_vals:
            for r in right_vals:
                if op == '*':
                    values.add(l * r)
                elif op == '+':
                    values.add(l + r)
                elif op == '-':
                    values.add(l - r)
                elif op == '/':
                    if r != 0:
                        values.add(l / r)
    return values

nums = [2, 3, 4, 5, 1]
ops = ['*', '*', '*', '+']
result = get_values(nums, ops)
print(f"Distinct values: {sorted(result)}")
print(f"Count: {len(result)}")"}

